 useEffect(()=>{if(!session?.user)return;const ch=supabase.channel("customer-orders-"+session.user.id).on("postgres_changes",{event:"UPDATE",schema:"public",table:"orders",filter:"user_id=eq."+session.user.id},payload=>{setOrders(x=>x.map(o=>o.id===payload.new.id?{...o,...payload.new}:o));setMessage("Order status updated · "+String(payload.new.status).replaceAll("_"," "));}).subscribe();return()=>{supabase.removeChannel(ch)}},[session?.user?.id]);
 async function loadBranches(){const{data}=await supabase.from("branches").select("id,name,code,city,state").eq("active",true).order("name");setBranches(data||[]);if(data?.[0])setBranch(data[0].id)}
