     <div className="veterinaryFeaturedGrid">{featured.map(p=><button className="veterinaryFeaturedCard" key={p.id} onClick={()=>{setPanel(null);setDetail(p)}}><div className="veterinaryFeaturedImage"><ProductImage product={p}/></div><small>{p.b||"Pet Care"}</small><b>{p.n}</b><span>{p.salt||"Pet health essential"}</span><strong>₹{p.p} {p.mrp&&<del>₹{p.mrp}</del>}</strong><span className="veterinaryCardCta">View product <ChevronRight size={13}/></span></button>)}</div>
